/**
 * Motivational quotes for the morning message.
 *
 * These are a hand-checked list in code, NOT generated by the model.
 * Tayyab asked for things people actually said, and language models are
 * notoriously bad at this — they produce fluent, plausible quotes and
 * attach them to the wrong person, or invent them wholesale. A short list
 * of verified lines is worth more than an endless supply of fake ones.
 *
 * Each entry carries where it comes from, so any of them can be checked.
 * Add more freely; the only rule is that you can point at a source.
 */
export interface Quote {
  text: string;
  who: string;
  /** Where it is recorded. Kept for verification, not shown to the user. */
  source: string;
}

