/**
 * A quote, avoiding the ones used most recently.
 *
 * Repeating yesterday's line makes the whole message feel automated,
 * which is the opposite of the point.
 */
export function pickQuote(recentTexts: string[] = []): Quote {
  const fresh = QUOTES.filter((q) => !recentTexts.some((r) => r.includes(q.text.slice(0, 40))));
  const pool = fresh.length > 0 ? fresh : QUOTES;
  return pool[Math.floor(Math.random() * pool.length)];
}

/** Formatted for WhatsApp. */
export function formatQuote(quote: Quote): string {
  return `"${quote.text}"\n— ${quote.who}`;
}
